import pdfplumber
import pandas as pd
import json

def extract_pdf_data(pdf_path):
    data = []
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            table = page.extract_table()
            if table:
                if not data:
                    headers = table[0]
                    data.extend(table[1:])
                else:
                    data.extend(table)
    return pd.DataFrame(data, columns=headers)

# Load data
pdf_df = extract_pdf_data('/root/employees_backup.pdf')
excel_df = pd.read_excel('/root/employees_current.xlsx')

# Numeric columns to handle
num_cols = ['Salary', 'Years', 'Score']

# Clean and convert PDF data types
for col in pdf_df.columns:
    if col in num_cols:
        pdf_df[col] = pd.to_numeric(pdf_df[col].astype(str).str.replace(',', '').str.replace('$', ''), errors='coerce')
    else:
        pdf_df[col] = pdf_df[col].astype(str)

# Clean and convert Excel data types
for col in excel_df.columns:
    if col in num_cols:
        excel_df[col] = pd.to_numeric(excel_df[col], errors='coerce')
    else:
        excel_df[col] = excel_df[col].astype(str)

# Set ID as index
pdf_df.set_index('ID', inplace=True)
excel_df.set_index('ID', inplace=True)

# 1. Deleted Employees
deleted_ids = sorted(list(set(pdf_df.index) - set(excel_df.index)))

# 2. Modified Employees
modified_employees = []
common_ids = sorted(list(set(pdf_df.index) & set(excel_df.index)))

for emp_id in common_ids:
    pdf_row = pdf_df.loc[emp_id]
    excel_row = excel_df.loc[emp_id]

    for col in pdf_df.columns:
        val_old = pdf_row[col]
        val_new = excel_row[col]

        # Comparison logic
        is_different = False
        if col in num_cols:
            if abs(val_old - val_new) > 1e-9: # Handle float precision
                is_different = True
        else:
            if val_old != val_new:
                is_different = True

        if is_different:
            # Ensure numeric types are native Python types for JSON
            def convert_val(v):
                if isinstance(v, (pd.Int64Dtype, pd.Series, pd.DataFrame)):
                    return v.item()
                if hasattr(v, 'item'):
                    return v.item()
                return v

            modified_employees.append({
                "id": emp_id,
                "field": col,
                "old_value": convert_val(val_old),
                "new_value": convert_val(val_new)
            })

# Sort modified_employees by ID
modified_employees.sort(key=lambda x: x['id'])

# Final Report
report = {
    "deleted_employees": deleted_ids,
    "modified_employees": modified_employees
}

with open('/root/diff_report.json', 'w') as f:
    json.dump(report, f, indent=2)

print("Report generated successfully.")
